template:
struct Hold<T> {
    val: T,
}

impl⟦s1⟧ Hold<T> {
    fn new(val: T) -> Self {
        Hold { val }
    }
}

impl Hold<⟦s2⟧> {
    fn speak(&self) -> &str {
        &self.val
    }
}

fn main() {
    let h1 = Hold::new(42);
    let h2 = Hold::new(String::from("hi"));
    println!("{} {}", h1.val, h2.speak());
}

tests:
#[test]
fn holds_generic_and_string() {
    let h1 = Hold::new(100);
    let h2 = Hold::new(String::from("hello"));
    assert_eq!(h1.val, 100);
    assert_eq!(h2.speak(), "hello");
}
